-	struct crypto_ahash *ahash = __crypto_ahash_cast(async_req->tfm);
-	struct qce_sha_reqctx *rctx = ahash_request_ctx_dma(req);
-	struct qce_alg_template *tmpl = to_ahash_tmpl(async_req->tfm);
-	struct qce_device *qce = tmpl->qce;
