-	__be32 mackey[QCE_SHA_HMAC_KEY_SIZE / sizeof(__be32)] = {0};
-	u32 auth_cfg = 0, config;
-	unsigned int iv_words;
-
-	/* if not the last, the size has to be on the block boundary */
-	if (!rctx->last_blk && req->nbytes % blocksize)
-		return -EINVAL;
