-		auth_cfg &= ~BIT(AUTH_LAST_SHIFT);
-
-	if (rctx->first_blk)
-		auth_cfg |= BIT(AUTH_FIRST_SHIFT);
-	else
-		auth_cfg &= ~BIT(AUTH_FIRST_SHIFT);
