-		rctx->authklen = QCE_SHA_HMAC_KEY_SIZE;
-	} else if (IS_CMAC(flags)) {
-		rctx->authkey = ctx->authkey;
-		rctx->authklen = AES_KEYSIZE_128;
-	}
-
-	rctx->src_nents = sg_nents_for_len(req->src, req->nbytes);
