+	signal = &sky1src->signals[id];
+	if (!signal->offset && !signal->bit)
+		return -EINVAL;
+
+	ret = regmap_read(sky1src->regmap, signal->offset, &value);
+	if (ret)
+		return ret;
 
-	regmap_read(sky1src->regmap, signal->offset, &value);
 	return !(value & signal->bit);
 }
 
